import kotlinx.coroutines.*

suspend fun loadPrice(name: String): Int {
    delay(100)
    return name.length * 10
}

fun main() = runBlocking {
    val price = loadPrice("хлеб")
    println("Цена: $price")
}

import kotlinx.coroutines.*

suspend fun loadPrice(name: String): Int {
    delay(100)
    return name.length * 10
}

fun main() = runBlocking {
    val a = async { loadPrice("хлеб") }
    val b = async { loadPrice("молоко") }
    println("Сумма: ${a.await() + b.await()}")
}

import androidx.lifecycle.ViewModel
import kotlinx.coroutines.*

class TasksViewModel(private val repo: Repo) : ViewModel() {
    fun refresh() {
        viewModelScope.launch {
            val tasks = withContext(Dispatchers.IO) { repo.load() }
            show(tasks)
        }
    }
}

import kotlinx.coroutines.*

suspend fun loadUser(id: Int): String {
    delay(50)
    if (id < 0) throw IllegalArgumentException("нет такого номера")
    return "Аня"
}

fun main() = runBlocking {
    try {
        println(loadUser(1))
        println(loadUser(-1))
    } catch (e: IllegalArgumentException) {
        println("Ошибка: ${e.message}")
    }
}

import kotlinx.coroutines.*

fun CoroutineScope.startLoading(): Job {
    val job = launch {
        repeat(1000) {
            ensureActive()
            // тяжёлый шаг загрузки
        }
    }
    return job
}

fun stop(job: Job) {
    job.cancel()
}
